const tickets = [
 {
  "id": "T-1001",
  "customer": "Priya Sharma",
  "subject": "Payment charged twice",
  "message": "I was charged twice for my invoice this month. This is unacceptable, please refund urgently."
 },
 {
  "id": "T-1002",
  "customer": "Rahul Verma",
  "subject": "App crashes on login",
  "message": "The app crashes every time I try to login. It is not working since the update and I am frustrated."
 },
 {
  "id": "T-1003",
  "customer": "Anita Desai",
  "subject": "Where is my order?",
  "message": "My order has not arrived yet. Can you share the delivery status?"
 },
 {
  "id": "T-1004",
  "customer": "Karan Mehta",
  "subject": "Great support, thanks",
  "message": "Thanks for the quick help yesterday. The team was great and very helpful."
 },
 {
  "id": "T-1005",
  "customer": "Sneha Iyer",
  "subject": "Reset password",
  "message": "I forgot my password and cannot access my account. Please help me reset it."
 },
 {
  "id": "T-1006",
  "customer": "Vikram Singh",
  "subject": "Dashboard is down",
  "message": "Our whole team cannot use the dashboard. It is down and this is urgent for our client demo."
 },
 {
  "id": "T-1007",
  "customer": "Meera Nair",
  "subject": "Invoice copy needed",
  "message": "Could you please send a copy of last month's invoice for our records?"
 },
 {
  "id": "T-1008",
  "customer": "Arjun Reddy",
  "subject": "Worst shipping experience",
  "message": "Delivery was late and the package arrived damaged. Terrible service, I want a refund."
 },
 {
  "id": "T-1009",
  "customer": "Divya Joshi",
  "subject": "Feature question",
  "message": "How do I export my data to a spreadsheet? I love the product so far."
 },
 {
  "id": "T-1010",
  "customer": "Rohan Gupta",
  "subject": "Bug in report page",
  "message": "There is an error on the report page, numbers do not match the export."
 },
 {
  "id": "T-1011",
  "customer": "Neha Kapoor",
  "subject": "Update my email",
  "message": "Please update the email on my account to my new address."
 },
 {
  "id": "T-1012",
  "customer": "Aditya Rao",
  "subject": "Payment failed",
  "message": "My payment failed twice and I am worried my subscription will stop. Please check."
 }
];
return tickets.map(t => ({ json: t }));

const NEG = ['angry','terrible','worst','unacceptable','frustrated','not working','crash','damaged','late','worried','down','refund','failed','error'];
const POS = ['thanks','great','love','helpful','happy','awesome'];
const CATS = {
  Billing:   ['invoice','refund','charge','charged','payment','subscription'],
  Technical: ['error','crash','bug','not working','login','dashboard','down'],
  Account:   ['password','account','access','email'],
  Shipping:  ['delivery','shipping','order','package','arrived']
};
const out = [];
for (const item of $input.all()) {
  const t = item.json;
  const text = (t.subject + ' ' + t.message).toLowerCase();
  const neg = NEG.filter(w => text.includes(w)).length;
  const pos = POS.filter(w => text.includes(w)).length;
  const sentiment = neg > pos ? 'Negative' : pos > neg ? 'Positive' : 'Neutral';
  let category = 'General';
  let best = 0;
  for (const [name, words] of Object.entries(CATS)) {
    const hits = words.filter(w => text.includes(w)).length;
    if (hits > best) { best = hits; category = name; }
  }
  const urgent = text.includes('urgent') || text.includes('down');
  let priority = 'Low';
  if (urgent || (sentiment === 'Negative' && (category === 'Billing' || category === 'Technical') && neg >= 2)) priority = 'High';
  else if (sentiment === 'Negative' || category === 'Billing' || category === 'Technical') priority = 'Medium';
  out.push({ json: { ...t, sentiment, category, priority } });
}
return out;

const items = $input.all().map(i => i.json);
const order = { High: 0, Medium: 1, Low: 2 };
items.sort((a, b) => order[a.priority] - order[b.priority] || a.id.localeCompare(b.id));
const esc = s => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const count = (key) => items.reduce((m, i) => (m[i[key]] = (m[i[key]] || 0) + 1, m), {});
const byPriority = count('priority'), byCategory = count('category'), bySentiment = count('sentiment');
const total = items.length;
const bars = (obj) => Object.entries(obj).map(([k, v]) =>
  `<div class="row"><span class="lab">${esc(k)}</span><span class="bar" style="width:${Math.round(v / total * 100) * 3}px"></span><span class="num">${v}</span></div>`).join('');
const rows = items.map(i => `<tr class="${i.priority.toLowerCase()}"><td>${esc(i.id)}</td><td>${esc(i.customer)}</td><td>${esc(i.subject)}</td><td>${esc(i.category)}</td><td>${esc(i.sentiment)}</td><td><b>${esc(i.priority)}</b></td><td>${esc(i.team)}</td><td>${esc(i.action)}</td><td>${i.sla_hours}h</td></tr>`).join('');
const date = new Date().toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' });
const html = `<!doctype html><html><head><meta charset="utf-8"><title>Support Triage Report</title><style>
body{font-family:Arial,sans-serif;color:#222;max-width:1100px;margin:30px auto;padding:0 20px}
h1{color:#1f3a5f;margin-bottom:0}.sub{color:#666;margin-top:4px}
.cards{display:flex;gap:14px;margin:20px 0}.card{flex:1;border:1px solid #ddd;border-radius:8px;padding:14px}
.card h2{margin:0;font-size:30px;color:#1f3a5f}.card p{margin:4px 0 0;color:#666}
.row{display:flex;align-items:center;gap:8px;margin:4px 0}.lab{width:90px}.bar{height:14px;background:#1f3a5f;border-radius:3px}
.grid{display:flex;gap:30px}.grid>div{flex:1}
table{border-collapse:collapse;width:100%;font-size:13px;margin-top:10px}th,td{border:1px solid #ddd;padding:6px 8px;text-align:left}
th{background:#1f3a5f;color:#fff}tr.high{background:#fdecea}tr.medium{background:#fff7e0}tr.low{background:#eef7ee}
</style></head><body>
<h1>Support Ticket Triage Report</h1><p class="sub">Generated ${date}</p>
<div class="cards">
<div class="card"><h2>${total}</h2><p>Total tickets</p></div>
<div class="card"><h2>${byPriority.High || 0}</h2><p>High priority</p></div>
<div class="card"><h2>${bySentiment.Negative || 0}</h2><p>Unhappy customers</p></div>
<div class="card"><h2>${byPriority.Low || 0}</h2><p>Low priority</p></div></div>
<div class="grid"><div><h3>By priority</h3>${bars(byPriority)}</div><div><h3>By category</h3>${bars(byCategory)}</div><div><h3>By sentiment</h3>${bars(bySentiment)}</div></div>
<h3>All tickets (most urgent first)</h3>
<table><tr><th>ID</th><th>Customer</th><th>Subject</th><th>Category</th><th>Sentiment</th><th>Priority</th><th>Assigned to</th><th>Action</th><th>Reply within</th></tr>${rows}</table>
</body></html>`;
const bin = await this.helpers.prepareBinaryData(Buffer.from(html, 'utf8'), 'support-triage-report.html', 'text/html');
return [{ json: { total, byPriority, byCategory, bySentiment, tip: 'Open the Binary tab and download support-triage-report.html' }, binary: { data: bin } }];
